CREATE FUNCTION public.equipment_measurement_is_internal(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.order_measurements m JOIN public.measurement_orders o ON o.id=m.order_id WHERE m.id=_id AND o.order_type='internal') $$;
REVOKE ALL ON FUNCTION public.equipment_measurement_is_internal(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.equipment_measurement_is_internal(uuid) TO authenticated;
ALTER POLICY internal_external_measurement_isolation ON public.order_measurements USING(NOT public.is_external_customer(auth.uid()) OR NOT public.equipment_measurement_is_internal(id));
CREATE FUNCTION public.get_equipment_audit(_equipment_id uuid) RETURNS TABLE(id uuid,event_type text,created_at timestamptz,metadata jsonb) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.equipment_can_read(_equipment_id) THEN RAISE EXCEPTION 'Nicht berechtigt' USING ERRCODE='42501'; END IF; RETURN QUERY SELECT a.id,a.event_type,a.created_at,a.metadata FROM public.activity_log a WHERE a.metadata->>'equipment_id'=_equipment_id::text ORDER BY a.created_at DESC; END $$;
REVOKE ALL ON FUNCTION public.get_equipment_audit(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_equipment_audit(uuid) TO authenticated;
CREATE FUNCTION public.equipment_assert_active(_id uuid,_expected uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(_id::text,0)); PERFORM 1 FROM public.test_equipment WHERE id=_id AND active_measurement_id=_expected FOR UPDATE; IF _expected IS NULL OR NOT FOUND THEN RAISE EXCEPTION 'Prüfauftrag wurde geändert. Ansicht aktualisieren.'; END IF; END $$;
REVOKE ALL ON FUNCTION public.equipment_assert_active(uuid,uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.start_equipment_check(_equipment_id uuid,_expected_measurement_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.equipment_assert_active(_equipment_id,_expected_measurement_id); PERFORM public.start_equipment_check(_equipment_id); END $$;
CREATE FUNCTION public.save_equipment_check_draft(_equipment_id uuid,_values jsonb,_expected_measurement_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.equipment_assert_active(_equipment_id,_expected_measurement_id); PERFORM public.save_equipment_check_draft(_equipment_id,_values); END $$;
CREATE FUNCTION public.record_equipment_check(_equipment_id uuid,_status text,_summary text,_notes text,_values jsonb,_expected_measurement_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.equipment_assert_active(_equipment_id,_expected_measurement_id); RETURN public.record_equipment_check(_equipment_id,_status,_summary,_notes,_values); END $$;
CREATE FUNCTION public.cancel_equipment_check_order(_equipment_id uuid,_reason text,_expected_measurement_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.equipment_assert_active(_equipment_id,_expected_measurement_id); PERFORM public.cancel_equipment_check_order(_equipment_id,_reason); END $$;
REVOKE EXECUTE ON FUNCTION public.start_equipment_check(uuid), public.save_equipment_check_draft(uuid,jsonb), public.record_equipment_check(uuid,text,text,text,jsonb), public.cancel_equipment_check_order(uuid,text) FROM authenticated;
REVOKE ALL ON FUNCTION public.start_equipment_check(uuid,uuid),public.save_equipment_check_draft(uuid,jsonb,uuid),public.record_equipment_check(uuid,text,text,text,jsonb,uuid),public.cancel_equipment_check_order(uuid,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.start_equipment_check(uuid,uuid),public.save_equipment_check_draft(uuid,jsonb,uuid),public.record_equipment_check(uuid,text,text,text,jsonb,uuid),public.cancel_equipment_check_order(uuid,text,uuid) TO authenticated;